function validate([s]) {
  if (typeof s !== 'string' || s.length < 3 || s.length > 100) return 's needs 3 to 100 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  const counts = [...new Set(s)].map(ch => s.split(ch).length - 1);
  if (!counts.some(c => c % 2 === 1)) return 'Some letter must occur an odd number of times.';
  if (!counts.some(c => c % 2 === 0)) return 'Some letter must occur an even number of times.';
  return null;
}

