function maxDifference(s) {
  const count = new Array(26).fill(0);
  for (const ch of s) {
    count[ch.charCodeAt(0) - 97]++;
  }
  let maxOdd = 0;
  let minEven = Infinity;
  for (const c of count) {
    if (c % 2 === 1) {
      maxOdd = Math.max(maxOdd, c);
    } else if (c > 0) {
      minEven = Math.min(minEven, c);
    }
  }
  return maxOdd - minEven;
}

