function maxDifference(s) {
  // Try every ordered pair of letters that occur, counting each one by splitting the string.
  const present = [...new Set(s)];
  let best = null;
  for (const a of present) {
    for (const b of present) {
      const odd = s.split(a).length - 1;
      const even = s.split(b).length - 1;
      if (odd % 2 === 1 && even % 2 === 0 && (best === null || odd - even > best)) best = odd - even;
    }
  }
  return best;
}

