function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  // Retry until some letter occurs an odd number of times and another an even number of times.
  for (;;) {
    const n = large ? 90 + pick(11) : 3 + pick(12);
    const kinds = large ? 3 + pick(24) : 2 + pick(4);
    const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(pick(27 - kinds)).slice(0, kinds);
    // Skewed choices give some letters many occurrences and others few.
    const s = Array.from({ length: n }, () => alphabet[Math.floor(alphabet.length * rand() ** 2)]).join('');
    const counts = [...new Set(s)].map(ch => s.split(ch).length - 1);
    if (counts.some(c => c % 2 === 1) && counts.some(c => c % 2 === 0)) return [s];
  }
}
